class Solution { public: vector<int> getBiggestThree(vector<vector<int>>& grid){int rows=grid.size(),cols=grid[0].size();set<int,greater<int>> sums;for(int row=0;row<rows;++row)for(int col=0;col<cols;++col){sums.insert(grid[row][col]);for(int radius=1;row+2*radius<rows&&col-radius>=0&&col+radius<cols;++radius){int sum=0;for(int step=0;step<radius;++step)sum+=grid[row+step][col+step]+grid[row+radius+step][col+radius-step]+grid[row+2*radius-step][col-step]+grid[row+radius-step][col-radius+step];sums.insert(sum);}}vector<int> answer;for(int sum:sums){if(answer.size()==3)break;answer.push_back(sum);}return answer;} };
